import numpy as np

class RippleValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Quadratic bowl term
        quadratic = np.sum(x**2)

        # Ripple term with varying frequencies and amplitudes
        ripple = 0.0
        for i in range(self.dim):
            ripple += np.sin(5 * np.pi * x[i]) * np.exp(-0.1 * np.abs(x[i]))

        # Combine terms with weights
        return quadratic + 0.5 * ripple
